    Object.assign(tile.style, {
      display: "inline-flex",
      flexDirection: "column",
      alignItems: "center",
      justifyContent: "flex-start",
      width: "74px",
      padding: "3px 3px",
      borderRadius: "3px",
      backgroundColor: levelInfo.foil ? "#4a3a10" : "#1b2838",
      boxSizing: "border-box"
    });
