    const pinnable = !!(boxRect && parent && typeof parent.getBoundingClientRect === "function");
    const already = pinnable ? parent.querySelector(".steamtools-rarity-tiles") : anchor.el.querySelector(".steamtools-rarity-tiles");
    if (already) return;
    // Tile row -- back to being the pinned element itself (not nested
    // inside a wrapping flex column with the button), so the pin math
    // below is measuring/placing exactly what it was originally tuned for.
    const tileRow = document.createElement("div");
    tileRow.className = "steamtools-rarity-tiles";
    Object.assign(tileRow.style, { display: "flex", flexWrap: "wrap", gap: "4px", justifyContent: "center", zIndex: "5" });
