    btn.title = "Refreshes your own full inventory, then checks every game where you hold a spare against already-cached friend data for a 1:1 trade.";
    const btnLabel = document.createElement("span");
    btnLabel.textContent = "Find 1:1 Card Trades";
    btn.appendChild(btnLabel);
    btn.addEventListener("click", () => {
      if (!expanded) { expanded = true; content.style.display = "block"; title.textContent = titleLabel(); }
      runBulkOneToOneScan().catch((e) => warn("BulkOneToOneMatcher", e?.message ?? e));
    });
    box.appendChild(btn);

    title.addEventListener("click", () => {
      expanded = !expanded;
      content.style.display = expanded ? "block" : "none";
      title.textContent = titleLabel();
    });

    const content = document.createElement("div");
