  function resumeAllScanning() {
    settings.set("scanningPaused", false);
    // Clicking Resume is an explicit "try now" signal -- don't leave the
    // person trapped behind a rate-limit cooldown that was only hidden
    // because the Pause/Resume button doesn't show the override option
    // while paused. This is the same override the "Try now anyway" button
    // performs; Resume should mean what it says.
    queue.clearRateLimit("steamcommunity.com");
    queue.clearRateLimit("api.steampowered.com");
    // Resume any explicitly requested single-account scans even when the
    // user has NOT consented to scanning their entire friends list.
    if (settings.get("featFriendIndex")) {
      if (settings.get("friendIndexConsentGiven")) startFriendIndexDrip();
      void runExplicitFriendScanQueue();
    }
    if (settings.get("featSecondDegreeFriends")) startSecondDegreeDrip();
    if (settings.get("featBoosterCreator")) startBoosterDrip();
    log("FriendIndex", "scanning resumed by user (rate-limit cooldown cleared)");
  }

